export function normalize(text){return String(text).toLocaleLowerCase('de').normalize('NFKC').replace(/ß/g,'ss').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();}
const index=new Map(Object.entries(FAQ).flatMap(([id,f])=>f.questions.map(q=>[normalize(q),id])));
const STOP=new Set('der die das ein eine einen einem einer und oder ist sind was wie wo wer wann warum gibt es ich du sie mir mich mein meine dein ihr euch kann können koennen muss für fuer mit bei von zu zum zur im in auf an den dem des nach über ueber auch noch man wird werden habe hat haben bitte gerne lane switch laneswitch'.split(' '));
const words=q=>normalize(q).split(' ').filter(w=>w.length>1&&!STOP.has(w));
// Ranks entries by keyword/title overlap (prefix match covers German inflections). Deterministic, no AI.
export function rank(question){
  const ws=words(question);if(!ws.length)return [];
  return Object.entries(FAQ).map(([id,f])=>{const keys=[...f.keywords.map(normalize),...words(f.title)];let score=0;
    for(const w of ws){if(keys.includes(w))score+=2;else if(keys.some(k=>k.length>3&&w.length>3&&(k.startsWith(w.slice(0,5))||w.startsWith(k.slice(0,5)))))score+=1;}
    return {id,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);
}
const PRIVATE=/\b(passwort ist|vertragsnummer|kontonummer|iban|versichertennummer|schadennummer|diagnose|krankheit|gesundheit)\b/;
const BLOCK=/\b(ignoriere|ignore|systemprompt|system prompt|garantiert|garantie|garantieren|versprich|kündigen|kuendigen|provision|vergütung|verguetung|gedeckt|deckt|steuerberatung)\b/;
export function classifyLocal(question){
  const q=normalize(question);
  if(!q)return {kind:'empty'};
  if(/@|\b\d[\d\s+()-]{6,}\b/.test(question)||PRIVATE.test(q))return {kind:'private'};
  // Exact approved question: immediate curated answer.
  if(index.has(q))return {kind:'answer',id:index.get(q)};
  if(/^(was kostet (das|es)|ist (das|es) (kostenlos|kostenfrei)|wie teuer ist (das|es)|kosten|preis)$/.test(q))return {kind:'clarify',ids:['kosten','versicherung']};
  if(BLOCK.test(q))return {kind:'contact'};
  const r=rank(question);
  // A clearly leading match is answered with its curated, reviewed text (no AI, no generated wording).
  if(r.length&&r[0].score>=3&&(r.length===1||r[0].score>=r[1].score+2))return {kind:'answer',id:r[0].id,matched:true};
  return r.length?{kind:'suggest',ids:r.slice(0,3).map(x=>x.id)}:{kind:'contact'};
}

// Individual commitments, private data and manipulation attempts always go to a person, never to AI.
export function canUseAI(question){
  const q=normalize(question);
  return !!q&&!/@|\b\d[\d\s+()-]{6,}\b/.test(question)&&!PRIVATE.test(q)&&!BLOCK.test(q)&&classifyLocal(question).kind!=='clarify';
}
